//! Deterministic audio fixtures and WAV I/O.
//!
//! Every fixture is synthesized from a closed-form formula (plus one fixed
//! xorshift seed for the noise component) so the committed WAVs can be
//! regenerated byte-for-byte. `fixture_gen` writes them to
//! `tests/fixtures/samples/` and records their SHA-256 in
//! `tests/fixtures/manifest.json`.

use std::error::Error;
use std::f32::consts::TAU;
use std::fmt;
use std::path::Path;

use drumpad_engine::voice::{LoopPoints, PlayMode, Playback};
use drumpad_samples::decode::AudioData;
use drumpad_samples::resample::ResampleError;
use sha2::{Digest, Sha256};

/// Default fixture sample rate.
pub const FIXTURE_SAMPLE_RATE: u32 = 48_000;

/// Names of the committed fixtures, in manifest order.
pub const FIXTURE_NAMES: [&str; 6] = ["choke", "gate", "hot", "loop", "one_shot", "pitch"];

/// Fixtures that are rendered with a non-default playback mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FixtureSpec {
    /// File name stem.
    pub name: &'static str,
    /// Frames the fixture occupies.
    pub frames: usize,
    /// Playback mode the fixture is designed for.
    pub mode: PlayMode,
}

/// Description of every committed fixture.
pub const FIXTURES: [FixtureSpec; 6] = [
    FixtureSpec {
        name: "choke",
        frames: 24_000,
        mode: PlayMode::OneShot,
    },
    FixtureSpec {
        name: "gate",
        frames: 96_000,
        mode: PlayMode::Gate,
    },
    FixtureSpec {
        name: "hot",
        frames: 24_000,
        mode: PlayMode::OneShot,
    },
    FixtureSpec {
        name: "loop",
        frames: 256,
        mode: PlayMode::Loop,
    },
    FixtureSpec {
        name: "one_shot",
        frames: 3_840,
        mode: PlayMode::OneShot,
    },
    FixtureSpec {
        name: "pitch",
        frames: 4_800,
        mode: PlayMode::OneShot,
    },
];

/// Look up a fixture by name.
pub fn fixture_spec(name: &str) -> Option<FixtureSpec> {
    FIXTURES.into_iter().find(|spec| spec.name == name)
}

/// Synthesize one fixture as mono `f32` at `sample_rate`.
///
/// Returns `None` for an unknown name. The formulas are deliberately simple so
/// the expected shape is obvious in a diff: no filters, no envelopes beyond a
/// single exponential decay.
pub fn synthesize(name: &str, sample_rate: u32) -> Option<Vec<f32>> {
    let spec = fixture_spec(name)?;
    let rate = sample_rate.max(1) as f32;
    let frames = spec.frames;
    let mut data = Vec::with_capacity(frames);
    match name {
        "one_shot" => {
            // A click at frame zero followed by a short pitched decay so the
            // onset is trivially detectable.
            for frame in 0..frames {
                let time = frame as f32 / rate;
                let envelope = (-time / 0.03).exp();
                let mut value = 0.8 * envelope * (TAU * 180.0 * time).sin();
                if frame == 0 {
                    value = 0.8;
                }
                data.push(value);
            }
        }
        "gate" => {
            // A steady tone; the gate release is applied by the engine when
            // the sequence sends note_off.
            for frame in 0..frames {
                let time = frame as f32 / rate;
                data.push(0.5 * (TAU * 440.0 * time).sin());
            }
        }
        "loop" => {
            // Exactly two cycles in 256 frames, so frame 0 and frame 255 join
            // without a discontinuity.
            let frequency = 2.0 * rate / frames as f32;
            for frame in 0..frames {
                let time = frame as f32 / rate;
                data.push(0.5 * (TAU * frequency * time).sin());
            }
        }
        "choke" => {
            for frame in 0..frames {
                let time = frame as f32 / rate;
                let envelope = (-time / 0.25).exp();
                data.push(0.7 * envelope * (TAU * 600.0 * time).sin());
            }
        }
        "pitch" => {
            for frame in 0..frames {
                let time = frame as f32 / rate;
                data.push(0.5 * (TAU * 1_000.0 * time).sin());
            }
        }
        "hot" => {
            // Three detuned partials at high amplitude; a single voice peaks
            // near full scale and several voices sum well past it, which is
            // what the limiter golden test needs.
            for frame in 0..frames {
                let time = frame as f32 / rate;
                let value = (TAU * 110.0 * time).sin()
                    + (TAU * 220.0 * time).sin()
                    + (TAU * 330.0 * time).sin();
                data.push(0.32 * value);
            }
        }
        _ => return None,
    }
    Some(data)
}

/// Build a deterministic `SampleBuffer` for a named fixture.
pub fn buffer(name: &str) -> Option<drumpad_engine::voice::SampleBuffer> {
    let spec = fixture_spec(name)?;
    let data = synthesize(name, FIXTURE_SAMPLE_RATE)?;
    let buffer = drumpad_engine::voice::SampleBuffer::from_mono(data, FIXTURE_SAMPLE_RATE).ok()?;
    (buffer.frame_count() == spec.frames).then_some(buffer)
}

/// One pad's fixture assignment.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct PadFixture {
    /// Sample bank slot.
    pub slot: u16,
    /// Linear pad gain.
    pub gain: f32,
    /// Pan in `-1.0..=1.0`.
    pub pan: f32,
    /// Tuning in cents.
    pub tune_cents: i32,
    /// Choke group, `0` for none.
    pub choke_group: u8,
    /// Playback mode and loop points.
    pub playback: Playback,
}

impl PadFixture {
    /// A one-shot at unity gain, centred.
    pub const fn one_shot(slot: u16) -> Self {
        Self {
            slot,
            gain: 1.0,
            pan: 0.0,
            tune_cents: 0,
            choke_group: 0,
            playback: Playback {
                mode: PlayMode::OneShot,
                loop_points: LoopPoints {
                    start: 0,
                    end: 0,
                    crossfade: 0,
                },
            },
        }
    }
}

/// A complete deterministic fixture bank and the pad layout that uses it.
#[derive(Debug, Clone)]
pub struct FixtureBank {
    /// Immutable samples shared with the engine.
    pub bank: drumpad_engine::voice::SampleBank,
    /// Fixture assignment per pad.
    pub pads: [PadFixture; 16],
}

impl FixtureBank {
    /// Build the standard 16-pad fixture layout.
    ///
    /// | Pads | Fixture | Notes |
    /// | --- | --- | --- |
    /// | 0 | `one_shot` | choke group 1 |
    /// | 1 | `choke` | choke group 1 |
    /// | 2 | `gate` | gate mode |
    /// | 3 | `loop` | loop mode |
    /// | 4 | `pitch` | tune +700 cents, pan left |
    /// | 5 | `hot` | limiter stress |
    /// | 6..16 | cycle 0..5 | varied gain/pan |
    pub fn standard() -> Self {
        let mut bank = drumpad_engine::voice::SampleBank::new();
        let mut slots = [0u16; 6];
        for (index, name) in ["one_shot", "choke", "gate", "loop", "pitch", "hot"]
            .iter()
            .enumerate()
        {
            let sample = buffer(name).expect("fixture must exist");
            slots[index] = bank.push(std::sync::Arc::new(sample));
        }

        let mut pads = [PadFixture::one_shot(slots[0]); 16];
        pads[0] = PadFixture {
            choke_group: 1,
            ..PadFixture::one_shot(slots[0])
        };
        pads[1] = PadFixture {
            choke_group: 1,
            ..PadFixture::one_shot(slots[1])
        };
        pads[2] = PadFixture {
            playback: Playback {
                mode: PlayMode::Gate,
                loop_points: LoopPoints::default(),
            },
            ..PadFixture::one_shot(slots[2])
        };
        pads[3] = PadFixture {
            playback: Playback {
                mode: PlayMode::Loop,
                loop_points: LoopPoints::full(FIXTURES[3].frames),
            },
            ..PadFixture::one_shot(slots[3])
        };
        pads[4] = PadFixture {
            gain: 0.8,
            pan: -0.5,
            tune_cents: 700,
            ..PadFixture::one_shot(slots[4])
        };
        for pad in 5..16 {
            let slot = slots[pad % slots.len()];
            pads[pad] = PadFixture {
                gain: 0.2 + (pad as f32 * 0.05),
                pan: ((pad as i32 % 5) as f32 - 2.0) / 2.0,
                tune_cents: (pad as i32 - 10) * 25,
                ..PadFixture::one_shot(slot)
            };
        }
        Self { bank, pads }
    }

    /// Build a one-sample bank from a named fixture, mapped to every pad.
    ///
    /// Useful for a focused goldens run (`--fixture gate`) where a single
    /// signal must be heard on any pad the sequence targets.
    pub fn single(name: &str) -> Option<Self> {
        let spec = fixture_spec(name)?;
        let sample = buffer(name)?;
        let mut bank = drumpad_engine::voice::SampleBank::new();
        let slot = bank.push(std::sync::Arc::new(sample));
        let playback = match spec.mode {
            PlayMode::Loop => Playback {
                mode: PlayMode::Loop,
                loop_points: LoopPoints::full(spec.frames),
            },
            mode => Playback {
                mode,
                loop_points: LoopPoints::default(),
            },
        };
        Some(Self {
            bank,
            pads: [PadFixture {
                playback,
                ..PadFixture::one_shot(slot)
            }; 16],
        })
    }

    /// Number of samples in the bank.
    pub fn len(&self) -> usize {
        self.bank.len()
    }

    /// True when the bank has no samples.
    pub fn is_empty(&self) -> bool {
        self.bank.is_empty()
    }
}

/// Fixture I/O errors.
#[derive(Debug)]
pub enum FixtureError {
    /// A fixture name is unknown.
    UnknownFixture(String),
    /// The WAV file could not be read or written.
    Wav {
        /// Path involved.
        path: String,
        /// Underlying hound error.
        source: hound::Error,
    },
    /// A decoded WAV has an unsupported shape.
    Shape(String),
    /// Filesystem access failed.
    Io {
        /// Path involved.
        path: String,
        /// Underlying IO error.
        source: std::io::Error,
    },
    /// JSON serialization failed.
    Json(serde_json::Error),
}

impl fmt::Display for FixtureError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::UnknownFixture(name) => write!(
                formatter,
                "unknown fixture {name:?}; expected one of {}",
                FIXTURE_NAMES.join(", ")
            ),
            Self::Wav { path, source } => write!(formatter, "WAV error for {path}: {source}"),
            Self::Shape(message) => write!(formatter, "unsupported WAV shape: {message}"),
            Self::Io { path, source } => write!(formatter, "I/O error for {path}: {source}"),
            Self::Json(error) => write!(formatter, "JSON error: {error}"),
        }
    }
}

impl Error for FixtureError {}

/// Read a WAV file into an engine sample buffer.
pub fn load_wav(
    path: impl AsRef<Path>,
) -> Result<drumpad_engine::voice::SampleBuffer, FixtureError> {
    let path = path.as_ref();
    let display = path.display().to_string();
    let mut reader = hound::WavReader::open(path).map_err(|source| FixtureError::Wav {
        path: display.clone(),
        source,
    })?;
    let spec = reader.spec();
    if spec.channels == 0 || spec.channels > 2 {
        return Err(FixtureError::Shape(format!(
            "{} channels; only mono and stereo are supported",
            spec.channels
        )));
    }
    if spec.sample_rate == 0 {
        return Err(FixtureError::Shape("sample rate is zero".to_owned()));
    }
    let samples: Result<Vec<f32>, hound::Error> = match spec.sample_format {
        hound::SampleFormat::Float => reader.samples::<f32>().collect(),
        hound::SampleFormat::Int => {
            let scale = 1.0 / (1i64 << (spec.bits_per_sample.saturating_sub(1))) as f32;
            reader
                .samples::<i32>()
                .map(|sample| sample.map(|value| value as f32 * scale))
                .collect()
        }
    };
    let samples = samples.map_err(|source| FixtureError::Wav {
        path: display.clone(),
        source,
    })?;
    let channels = u8::try_from(spec.channels).map_err(|_| {
        FixtureError::Shape(format!(
            "{} channels; only mono and stereo are supported",
            spec.channels
        ))
    })?;
    drumpad_engine::voice::SampleBuffer::new(samples, channels, spec.sample_rate)
        .map_err(|error| FixtureError::Shape(error.to_string()))
}

/// Write a sample buffer as a 32-bit float WAV.
///
/// Float WAV keeps the bytes exact across runs and avoids a quantization step
/// in golden comparisons.
pub fn write_wav(
    path: impl AsRef<Path>,
    buffer: &drumpad_engine::voice::SampleBuffer,
) -> Result<(), FixtureError> {
    let path = path.as_ref();
    let display = path.display().to_string();
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        std::fs::create_dir_all(parent).map_err(|source| FixtureError::Io {
            path: parent.display().to_string(),
            source,
        })?;
    }
    let spec = hound::WavSpec {
        channels: u16::from(buffer.channels()),
        sample_rate: buffer.sample_rate(),
        bits_per_sample: 32,
        sample_format: hound::SampleFormat::Float,
    };
    let mut writer = hound::WavWriter::create(path, spec).map_err(|source| FixtureError::Wav {
        path: display.clone(),
        source,
    })?;
    for sample in buffer.data() {
        writer
            .write_sample(*sample)
            .map_err(|source| FixtureError::Wav {
                path: display.clone(),
                source,
            })?;
    }
    writer.finalize().map_err(|source| FixtureError::Wav {
        path: display.clone(),
        source,
    })?;
    Ok(())
}

/// SHA-256 of a file, lower-case hex.
pub fn sha256_file(path: impl AsRef<Path>) -> Result<String, FixtureError> {
    let path = path.as_ref();
    let bytes = std::fs::read(path).map_err(|source| FixtureError::Io {
        path: path.display().to_string(),
        source,
    })?;
    let mut hasher = Sha256::new();
    hasher.update(&bytes);
    Ok(format!("{:x}", hasher.finalize()))
}

/// SHA-256 of a sample buffer's interleaved samples, in little-endian bits.
pub fn sha256_buffer(buffer: &drumpad_engine::voice::SampleBuffer) -> String {
    let mut hasher = Sha256::new();
    hasher.update(buffer.data().len().to_le_bytes());
    for sample in buffer.data() {
        hasher.update(sample.to_bits().to_le_bytes());
    }
    format!("{:x}", hasher.finalize())
}

/// Resample a mono fixture to `target_rate` with the real sample pipeline.
///
/// Used by the resampling benchmark and by tests that need a non-48 kHz
/// fixture. Returns `None` for an unknown fixture name.
pub fn resampled(name: &str, target_rate: u32) -> Option<Result<AudioData, ResampleError>> {
    let data = synthesize(name, FIXTURE_SAMPLE_RATE)?;
    let audio = AudioData::new(FIXTURE_SAMPLE_RATE, 1, data).ok()?;
    Some(drumpad_samples::resample::resample(&audio, target_rate))
}

/// Manifest entry for one generated fixture.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct FixtureManifestEntry {
    /// Fixture name.
    pub name: String,
    /// Relative path inside `tests/fixtures/`.
    pub file: String,
    /// Frame count.
    pub frames: usize,
    /// Channel count.
    pub channels: u8,
    /// Sample rate.
    pub sample_rate: u32,
    /// SHA-256 of the WAV file bytes.
    pub sha256: String,
}

/// The committed fixture manifest.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct FixtureManifest {
    /// Manifest schema version.
    pub schema_version: u32,
    /// Format of every fixture.
    pub sample_rate: u32,
    /// Generator name.
    pub generated_by: String,
    /// Entries in [`FIXTURE_NAMES`] order.
    pub fixtures: Vec<FixtureManifestEntry>,
}

/// Current fixture manifest schema version.
pub const FIXTURE_MANIFEST_SCHEMA_VERSION: u32 = 1;

/// Generate every fixture under `root` and write the manifest.
///
/// `root` is the `tests/fixtures` directory. Existing files are overwritten;
/// the result is deterministic, so a reviewer can regenerate and diff.
pub fn generate_all(root: impl AsRef<Path>) -> Result<FixtureManifest, FixtureError> {
    let root = root.as_ref();
    let samples_dir = root.join("samples");
    std::fs::create_dir_all(&samples_dir).map_err(|source| FixtureError::Io {
        path: samples_dir.display().to_string(),
        source,
    })?;
    let mut fixtures = Vec::new();
    for name in FIXTURE_NAMES {
        let buffer = buffer(name).ok_or_else(|| FixtureError::UnknownFixture(name.to_owned()))?;
        let relative = format!("samples/{name}.wav");
        let path = root.join(&relative);
        write_wav(&path, &buffer)?;
        fixtures.push(FixtureManifestEntry {
            name: name.to_owned(),
            file: relative,
            frames: buffer.frame_count(),
            channels: buffer.channels(),
            sample_rate: buffer.sample_rate(),
            sha256: sha256_file(&path)?,
        });
    }
    let manifest = FixtureManifest {
        schema_version: FIXTURE_MANIFEST_SCHEMA_VERSION,
        sample_rate: FIXTURE_SAMPLE_RATE,
        generated_by: format!("drumpad-tools {}", env!("CARGO_PKG_VERSION")),
        fixtures,
    };
    let json = serde_json::to_string_pretty(&manifest).map_err(FixtureError::Json)?;
    std::fs::write(root.join("manifest.json"), format!("{json}\n")).map_err(|source| {
        FixtureError::Io {
            path: root.join("manifest.json").display().to_string(),
            source,
        }
    })?;
    Ok(manifest)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_fixture_has_the_documented_length() {
        for spec in FIXTURES {
            let data = synthesize(spec.name, FIXTURE_SAMPLE_RATE).expect("fixture");
            assert_eq!(data.len(), spec.frames, "{}", spec.name);
            assert!(
                data.iter()
                    .all(|sample| sample.is_finite() && sample.abs() <= 1.0),
                "{} left the valid range",
                spec.name
            );
        }
        assert!(synthesize("nope", FIXTURE_SAMPLE_RATE).is_none());
    }

    #[test]
    fn loop_fixture_joins_seamlessly() {
        let data = synthesize("loop", FIXTURE_SAMPLE_RATE).expect("loop");
        let end = data[data.len() - 1];
        let next = data[1] - data[0];
        assert!(
            (end - data[0]).abs() < 0.05 || (end + next).abs() < 0.05,
            "loop endpoints are discontinuous: first {} last {end}",
            data[0]
        );
    }

    #[test]
    fn standard_bank_has_six_samples_and_sixteen_pads() {
        let fixture = FixtureBank::standard();
        assert_eq!(fixture.len(), 6);
        assert_eq!(fixture.pads.len(), 16);
        assert_eq!(fixture.pads[2].playback.mode, PlayMode::Gate);
        assert_eq!(fixture.pads[3].playback.mode, PlayMode::Loop);
        assert_eq!(fixture.pads[0].choke_group, 1);
        assert_eq!(fixture.pads[1].choke_group, 1);
    }

    #[test]
    fn wav_round_trip_is_bit_exact() {
        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.path().join("one_shot.wav");
        let original = buffer("one_shot").expect("fixture");
        write_wav(&path, &original).expect("write");
        let loaded = load_wav(&path).expect("read");
        assert_eq!(original.data(), loaded.data());
        assert_eq!(original.sample_rate(), loaded.sample_rate());
        assert_eq!(original.channels(), loaded.channels());
    }

    #[test]
    fn fixture_manifest_and_hashes_are_stable() {
        let dir = tempfile::tempdir().expect("tempdir");
        let first = generate_all(dir.path()).expect("generate");
        let second_dir = tempfile::tempdir().expect("tempdir");
        let second = generate_all(second_dir.path()).expect("generate");
        assert_eq!(first, second, "generation must be deterministic");
        for entry in &first.fixtures {
            assert_eq!(entry.sha256.len(), 64);
        }
    }
}
